def test_two_files_concatenated(run):
    r = run(args=['a.md', 'b.md'], files={'a.md': b'# A\n\npara one\n', 'b.md': b'continued\n\n- x\n'})
    assert r.stdout == b'<h1>A</h1>\n<p>para one\ncontinued</p>\n<ul>\n<li>x</li>\n</ul>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_files_join_mid_paragraph(run):
    r = run(args=['a.md', 'b.md'], files={'a.md': b'line without newline', 'b.md': b' joined\n'})
    assert r.stdout == b'<p>line without newline joined</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_files_join_fence(run):
    r = run(args=['a.md', 'b.md'], files={'a.md': b'```\ncode\n', 'b.md': b'more\n```\n'})
    assert r.stdout == b'<pre><code>code\nmore\n</code></pre>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_same_file_twice(run):
    r = run(args=['a.md', 'a.md'], files={'a.md': b'[x]\n\n[x]: /u\n'})
    assert r.stdout == b'<p><a href="/u">x</a></p>\n<p><a href="/u">x</a></p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


