def test_empty_input_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0" />\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_only_whitespace_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'   \n\n\t\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0" />\n'
    assert r.stderr == b''
    assert r.returncode == 0


