def test_all_flags(run):
    r = run(args=['--sourcepos', '--hardbreaks', '--nobreaks', '--smart', '--safe', '--unsafe', '--validate-utf8'], stdin=b'Line "one"\nline two -- <b>raw</b> [l](javascript:x)\n')
    assert r.stdout == b'<p data-sourcepos="1:1-2:40">Line \xe2\x80\x9cone\xe2\x80\x9d<br />\nline two \xe2\x80\x93 <b>raw</b> <a href="javascript:x">l</a></p>\n'
    assert r.stderr == b''
    assert r.returncode == 0
